    fn typed_parse<'a, T>(
        self,
        start: NonterminalId,
        tree_arena: &'a Arena,
        node: fn(ParseTree<'a>) -> T,
    ) -> Result<ParseSuccess<parse_tree::Start<T, &'a parse_tree::Layout<'a>>>, ParseError> {
        Ok(self.parse(start, tree_arena)?.map(|tree| {
            let root = tree.unwrap_start();
            parse_tree::Start {
                before: root.before.unwrap().unwrap_layout(),
                node: node(root.node),
                after: root.after.unwrap().unwrap_layout(),
                span: root.span,
            }
        }))
    }
    fn typed_parse_without_layout<'a, T>(
        self,
        start: NonterminalId,
        tree_arena: &'a Arena,
        node: fn(ParseTree<'a>) -> T,
    ) -> Result<ParseSuccess<parse_tree::Start<T, ()>>, ParseError> {
        Ok(self.parse(start, tree_arena)?.map(|tree| {
            let root = tree.unwrap_start();
            parse_tree::Start {
                before: (),
                node: node(root.node),
                after: (),
                span: root.span,
            }
        }))
    }
    #[inline(never)]
    #[allow(clippy::too_many_arguments)]
    fn create_symbol(
        &mut self,
        sppf_node_id: Option<SPPFNodeId>,
        gss_node_id: GssNodeId,
        return_slot: SlotId,
        env: Option<EnvId>,
        p: i32,
    ) {
        record!(self, Call, sppf_node_id, gss_node_id, return_slot);
        let i = match sppf_node_id {
            Some(id) => self.sppf_node(id).right_extent(),
            None => self.gss_node(gss_node_id).index,
        };
        // If there is already a GSS node for this call, add an edge.
        if let Some(existing_gss_node_id) = self.get_gss_node_symbol(i, p) {
            record!(self, GSSNodeFound, NonterminalId(69), i);
            self.add_edge_to_existing_gss_node(
                existing_gss_node_id,
                gss_node_id,
                sppf_node_id,
                return_slot,
                env,
            );
            return;
        }
        let alternatives = self.predict(&PREDICTION_SYMBOL, i);
        if !alternatives.is_empty() {
            record!(self, GSSNodeNotFound, NonterminalId(69), i);
            let new_gss_node_id = self.new_gss_node(NonterminalId(69), i);
            self.add_gss_edge(new_gss_node_id, gss_node_id, sppf_node_id, return_slot, env);
            let arena = self.vec_arena;
            let (env_id, env) = self.new_env();
            env.bind(BINDING_P, p, arena);
            self.add_first_descriptors(
                NonterminalId(69),
                i,
                new_gss_node_id,
                Some(env_id),
                alternatives,
            );
            self.add_gss_node_symbol(i, p, new_gss_node_id);
        } else {
            // The call symbol precedes the return slot in its alternative, so the return slot is never
            // at the first position.
            let call_slot = IggyGrammar::previous_slot(return_slot)
                .expect("a return slot follows the call symbol");
            self.add_failure(
                i,
                call_slot,
                Some(gss_node_id),
                GLLFailureKind::NoViableAlternative(&PREDICTION_SYMBOL),
            );
        }
    }
