    #[inline(always)]
    fn ll1_body_plus_11(&mut self, i: u32) -> Option<(u32, SPPFNodeId)> {
        let left_extent = i;
        let (base_pos_0, base_node_0) = self.ll1_parse_alt_0(i, None)?;
        let mut current = base_node_0;
        let mut j = base_pos_0;
        current = self.add_nonterminal_node(NonterminalNode {
            nonterminal_id: NonterminalId(44),
            return_slot: SlotId(278),
            span: Span {
                left_extent,
                right_extent: j,
            },
            child: current,
            ambiguous: false,
        });
        #[allow(clippy::while_let_loop)]
        loop {
            let Some((pos_0, node_0)) = self.ll1_parse_alt_0(j, None) else {
                break;
            };
            j = pos_0;
            current =
                self.create_intermediate_node_ll1(SlotId(276), left_extent, pos_0, current, node_0);
            current = self.add_nonterminal_node(NonterminalNode {
                nonterminal_id: NonterminalId(44),
                return_slot: SlotId(276),
                span: Span {
                    left_extent,
                    right_extent: j,
                },
                child: current,
                ambiguous: false,
            });
        }
        Some((j, current))
    }
